BEGIN;
CREATE SEQUENCE finance_asset_number AS BIGINT MINVALUE 1 MAXVALUE 9999999999 NO CYCLE;
CREATE TABLE "FinanceAsset"(id UUID PRIMARY KEY,number TEXT NOT NULL UNIQUE,tag TEXT NOT NULL CHECK(tag=upper(tag) AND tag~'^[A-Z0-9._-]{3,40}$'),description TEXT NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 1000),location TEXT NOT NULL CHECK(length(trim(location)) BETWEEN 1 AND 160),"custodianId" UUID REFERENCES "Person" ON DELETE RESTRICT,"billLineId" UUID REFERENCES "FinanceBillLine" ON DELETE RESTRICT,"fundingMovementId" UUID REFERENCES "FinanceMovement" ON DELETE RESTRICT,"accountId" UUID NOT NULL REFERENCES "FinanceAccount" ON DELETE RESTRICT,cost NUMERIC(20,2) NOT NULL CHECK(cost>0),"purchaseDate" DATE NOT NULL,"sourcePostingDate" DATE NOT NULL,"sourceSnapshot" JSONB NOT NULL,"inServiceDate" DATE NOT NULL CHECK("inServiceDate">="purchaseDate" AND "inServiceDate"<=DATE '9999-12-31'),"usefulLifeMonths" INTEGER NOT NULL CHECK("usefulLifeMonths" BETWEEN 1 AND 1200),"residualValue" NUMERIC(20,2) NOT NULL DEFAULT 0 CHECK("residualValue" BETWEEN 0 AND cost),"depreciationMethod" TEXT NOT NULL DEFAULT 'STRAIGHT_LINE' CHECK("depreciationMethod"='STRAIGHT_LINE'),convention TEXT NOT NULL DEFAULT 'PENDING' CHECK(convention IN('PENDING','FULL_MONTH_FROM_FIRST_MONTH')),"firstDepMonth" TEXT,"policyEvidence" TEXT,"accumulatedDepreciation" NUMERIC(20,2) NOT NULL DEFAULT 0 CHECK("accumulatedDepreciation"=0),"disposalDate" DATE CHECK("disposalDate" IS NULL),"disposalJournalId" UUID REFERENCES "FinanceJournalEntry" ON DELETE RESTRICT CHECK("disposalJournalId" IS NULL),"usedAt" TIMESTAMPTZ CHECK("usedAt" IS NULL),state TEXT NOT NULL DEFAULT 'REGISTERED' CHECK(state IN('REGISTERED','VOIDED')),version INTEGER NOT NULL DEFAULT 1 CHECK(version>0),"createdById" UUID NOT NULL REFERENCES "Person" ON DELETE RESTRICT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK(num_nonnulls("billLineId","fundingMovementId")=1),CHECK((convention='PENDING' AND "firstDepMonth" IS NULL) OR(convention='FULL_MONTH_FROM_FIRST_MONTH' AND "firstDepMonth"~'^[0-9]{4}-(0[1-9]|1[0-2])$' AND "firstDepMonth">='0001-01' AND length(trim("policyEvidence")) BETWEEN 3 AND 1000)));
CREATE UNIQUE INDEX "FinanceAsset_active_tag_key" ON "FinanceAsset"(tag) WHERE state='REGISTERED';
CREATE INDEX "FinanceAsset_tag_idx" ON "FinanceAsset"(tag);
CREATE INDEX "FinanceAsset_billLineId_idx" ON "FinanceAsset"("billLineId");
CREATE INDEX "FinanceAsset_fundingMovementId_idx" ON "FinanceAsset"("fundingMovementId");
CREATE TRIGGER "FinanceAsset_config" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceAsset" FOR EACH STATEMENT EXECUTE FUNCTION encova_finance_config_lock();
CREATE FUNCTION encova_finance_asset_source(bill_line UUID,funding_movement UUID) RETURNS TABLE("accountId" UUID,"documentDate" DATE,"postingDate" DATE,"eligibleCost" NUMERIC,snapshot JSONB) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT l."costAccountId",b."billDate",b."postingDate",cost.amount,jsonb_build_object('sourceType','BILL_LINE','billId',b.id,'number',b.number,'lineId',l.id,'description',l.description,'originalNetCost',l."netAmount"::text,'recoverableTax',l."taxAmount"::text,'eligibleCost',cost.amount::text,'party',b."partySnapshot",'evidence',b.evidence) FROM public."FinanceBillLine" l JOIN public."FinanceBill" b ON b.id=l."billId" JOIN public."FinanceAccount" a ON a.id=l."costAccountId" CROSS JOIN LATERAL(SELECT coalesce(sum(debit-credit),0) AS amount FROM public."FinanceJournalLine" WHERE "billLineId"=l.id AND "accountId"=l."costAccountId")cost WHERE funding_movement IS NULL AND l.id=bill_line AND b.state='POSTED' AND l.treatment='ASSET' AND a."controlType"='FIXED_ASSET'
 UNION ALL SELECT d."counterAccountId",d."documentDate",d."postingDate",cost.amount,jsonb_build_object('sourceType','FUNDING_MOVEMENT','number',d.number,'movementId',d.id,'description',d.description,'eligibleCost',cost.amount::text,'sourceSnapshot',d."sourceSnapshot",'evidence',d.evidence) FROM public."FinanceMovement" d JOIN public."FinanceAccount" a ON a.id=d."counterAccountId" CROSS JOIN LATERAL(SELECT coalesce(sum(l.debit-l.credit),0) AS amount FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" JOIN public."FinanceMovement" m ON m.id=e."movementId" WHERE(m.id=d.id OR m."reversalOfId"=d.id) AND l."accountId"=d."counterAccountId")cost WHERE bill_line IS NULL AND d.id=funding_movement AND d.state='POSTED' AND d.kind IN('NONCASH_CAPITAL','FOUNDER_OUTLAY') AND a."controlType"='FIXED_ASSET';
$$;
CREATE FUNCTION encova_finance_asset_check_source(bill_line UUID,funding_movement UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE allocated NUMERIC;available NUMERIC;BEGIN
 IF bill_line IS NULL AND funding_movement IS NULL THEN RETURN;END IF;
 SELECT coalesce(sum(cost),0) INTO allocated FROM public."FinanceAsset" WHERE state='REGISTERED' AND "billLineId" IS NOT DISTINCT FROM bill_line AND "fundingMovementId" IS NOT DISTINCT FROM funding_movement;
 IF allocated<=0 THEN RETURN;END IF;SELECT "eligibleCost" INTO available FROM public.encova_finance_asset_source(bill_line,funding_movement);
 IF available IS NULL OR allocated>available THEN RAISE EXCEPTION 'FINANCE_ASSET_SOURCE_CAPACITY' USING ERRCODE='P0001';END IF;
END $$;
CREATE FUNCTION encova_finance_asset_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE source RECORD;BEGIN
 IF TG_OP='DELETE' OR(TG_OP='UPDATE' AND OLD.state='VOIDED') THEN RAISE EXCEPTION 'FINANCE_ASSET_IMMUTABLE' USING ERRCODE='P0001';END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.number,NEW."billLineId",NEW."fundingMovementId",NEW."accountId",NEW.cost,NEW."purchaseDate",NEW."sourcePostingDate",NEW."sourceSnapshot",NEW."createdById",NEW."createdAt") IS DISTINCT FROM ROW(OLD.id,OLD.number,OLD."billLineId",OLD."fundingMovementId",OLD."accountId",OLD.cost,OLD."purchaseDate",OLD."sourcePostingDate",OLD."sourceSnapshot",OLD."createdById",OLD."createdAt") THEN RAISE EXCEPTION 'FINANCE_ASSET_IMMUTABLE' USING ERRCODE='P0001';END IF;
  IF NEW.version<>OLD.version+1 THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF NEW.state='VOIDED' AND(to_jsonb(NEW)-ARRAY['state','version','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','version','updatedAt']) THEN RAISE EXCEPTION 'FINANCE_ASSET_IMMUTABLE' USING ERRCODE='P0001';END IF;
 ELSE
  SELECT * INTO source FROM public.encova_finance_asset_source(NEW."billLineId",NEW."fundingMovementId");
  IF NEW.state<>'REGISTERED' OR NEW.version<>1 OR source."accountId" IS NULL OR ROW(NEW."accountId",NEW."purchaseDate",NEW."sourcePostingDate",NEW."sourceSnapshot") IS DISTINCT FROM ROW(source."accountId",source."documentDate",source."postingDate",source.snapshot) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."accountId" AND active AND "isPosting" AND "controlType"='FIXED_ASSET') THEN RAISE EXCEPTION 'FINANCE_ASSET_SOURCE' USING ERRCODE='P0001';END IF;
 END IF;
 IF(TG_OP='INSERT' OR NEW."custodianId" IS DISTINCT FROM OLD."custodianId") AND NEW."custodianId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=NEW."custodianId" AND status='ACTIVE') THEN RAISE EXCEPTION 'FINANCE_ASSET_CUSTODIAN' USING ERRCODE='P0001';END IF;
 IF NEW.convention='FULL_MONTH_FROM_FIRST_MONTH' AND(NEW."firstDepMonth" IS NULL OR NEW."policyEvidence" IS NULL OR length(trim(NEW."policyEvidence")) NOT BETWEEN 3 AND 1000 OR(NEW."firstDepMonth"||'-01')::date<date_trunc('month',greatest(NEW."inServiceDate",NEW."sourcePostingDate"))) THEN RAISE EXCEPTION 'FINANCE_ASSET_POLICY' USING ERRCODE='P0001';END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER "FinanceAsset_guard" BEFORE INSERT OR UPDATE OR DELETE ON "FinanceAsset" FOR EACH ROW EXECUTE FUNCTION encova_finance_asset_guard();
CREATE FUNCTION encova_finance_asset_check_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE entry UUID;movement public."FinanceMovement"%ROWTYPE;BEGIN
 IF TG_TABLE_NAME='FinanceAsset' THEN PERFORM public.encova_finance_asset_check_source(NEW."billLineId",NEW."fundingMovementId");
 ELSE
  IF NEW."billLineId" IS NOT NULL THEN PERFORM public.encova_finance_asset_check_source(NEW."billLineId",NULL);END IF;
  SELECT m.* INTO movement FROM public."FinanceJournalEntry" e JOIN public."FinanceMovement" m ON m.id=e."movementId" WHERE e.id=NEW."journalId";
  IF movement.id IS NOT NULL THEN PERFORM public.encova_finance_asset_check_source(NULL,coalesce(movement."reversalOfId",movement.id));END IF;
 END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER "FinanceAsset_source_valid" AFTER INSERT OR UPDATE ON "FinanceAsset" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_asset_check_trigger();
CREATE CONSTRAINT TRIGGER "FinanceJournalLine_asset_source_valid" AFTER INSERT ON "FinanceJournalLine" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_asset_check_trigger();
CREATE FUNCTION encova_finance_asset_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE item public."FinanceAsset"%ROWTYPE;prior public."FinanceLedgerReceipt"%ROWTYPE;source RECORD;reason TEXT;digest TEXT;result JSONB;BEGIN
 IF action IS NULL OR action NOT IN('CREATE','UPDATE','VOID') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 reason:=trim(input->>'reason');IF reason IS NULL OR length(reason) NOT BETWEEN 3 AND 500 OR input-(CASE WHEN action='CREATE' THEN ARRAY['tag','description','location','custodianId','billLineId','fundingMovementId','cost','inServiceDate','usefulLifeMonths','residualValue','depreciationMethod','convention','firstDepMonth','policyEvidence','reason'] WHEN action='UPDATE' THEN ARRAY['id','expectedVersion','tag','description','location','custodianId','inServiceDate','usefulLifeMonths','residualValue','depreciationMethod','convention','firstDepMonth','policyEvidence','reason'] ELSE ARRAY['id','expectedVersion','reason'] END)<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT public.encova_finance_session_ok(actor,provider,session_id) OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 digest:=encode(sha256(convert_to(jsonb_strip_nulls(input)::text,'UTF8')),'hex');SELECT * INTO prior FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation='ASSET_'||action AND key=request_key;
 IF FOUND THEN IF prior."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN prior.result;END IF;
 PERFORM pg_advisory_xact_lock(629815);
 IF action<>'CREATE' THEN
  IF jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO item FROM public."FinanceAsset" WHERE id=(input->>'id')::uuid FOR UPDATE;
  IF item.id IS NULL THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
  IF item.version<>(input->>'expectedVersion')::integer THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF item.state<>'REGISTERED' THEN RAISE EXCEPTION 'FINANCE_ASSET_IMMUTABLE' USING ERRCODE='P0001';END IF;
 END IF;
 IF action IN('CREATE','UPDATE') THEN
  IF jsonb_typeof(input->'residualValue') IS DISTINCT FROM 'string' OR input->>'residualValue' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$' OR jsonb_typeof(input->'usefulLifeMonths') IS DISTINCT FROM 'number' OR input->>'inServiceDate' IS NULL OR input->>'inServiceDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF action='CREATE' THEN
   IF jsonb_typeof(input->'cost') IS DISTINCT FROM 'string' OR input->>'cost' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$' OR(input->>'cost')::numeric<=0 OR num_nonnulls(input->>'billLineId',input->>'fundingMovementId')<>1 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
   SELECT * INTO source FROM public.encova_finance_asset_source((input->>'billLineId')::uuid,(input->>'fundingMovementId')::uuid);
   IF source."accountId" IS NULL THEN RAISE EXCEPTION 'FINANCE_ASSET_SOURCE' USING ERRCODE='P0001';END IF;
   INSERT INTO public."FinanceAsset"(id,number,tag,description,location,"custodianId","billLineId","fundingMovementId","accountId",cost,"purchaseDate","sourcePostingDate","sourceSnapshot","inServiceDate","usefulLifeMonths","residualValue","depreciationMethod",convention,"firstDepMonth","policyEvidence","createdById") VALUES(gen_random_uuid(),'AST-'||lpad(nextval('public.finance_asset_number')::text,10,'0'),input->>'tag',input->>'description',input->>'location',(input->>'custodianId')::uuid,(input->>'billLineId')::uuid,(input->>'fundingMovementId')::uuid,source."accountId",(input->>'cost')::numeric,source."documentDate",source."postingDate",source.snapshot,(input->>'inServiceDate')::date,(input->>'usefulLifeMonths')::integer,(input->>'residualValue')::numeric,input->>'depreciationMethod',input->>'convention',input->>'firstDepMonth',input->>'policyEvidence',actor) RETURNING * INTO item;
  ELSE
   UPDATE public."FinanceAsset" SET tag=input->>'tag',description=input->>'description',location=input->>'location',"custodianId"=(input->>'custodianId')::uuid,"inServiceDate"=(input->>'inServiceDate')::date,"usefulLifeMonths"=(input->>'usefulLifeMonths')::integer,"residualValue"=(input->>'residualValue')::numeric,"depreciationMethod"=input->>'depreciationMethod',convention=input->>'convention',"firstDepMonth"=input->>'firstDepMonth',"policyEvidence"=input->>'policyEvidence',version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=item.id RETURNING * INTO item;
  END IF;
 ELSE UPDATE public."FinanceAsset" SET state='VOIDED',version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=item.id RETURNING * INTO item;END IF;
 result:=jsonb_build_object('id',item.id,'number',item.number,'version',item.version);
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,'ASSET_'||action,request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_ASSET_'||action,'FinanceAsset',item.id,reason,jsonb_build_object('snapshot',to_jsonb(item)||jsonb_build_object('cost',item.cost::text,'residualValue',item."residualValue"::text,'accumulatedDepreciation',item."accumulatedDepreciation"::text)),request_id);RETURN result;
 EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'FINANCE_DUPLICATE' USING ERRCODE='P0001';WHEN check_violation OR not_null_violation OR foreign_key_violation OR invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';
END $$;
DO $$ DECLARE item RECORD;role_name TEXT;BEGIN
 ALTER TABLE "FinanceAsset" ENABLE ROW LEVEL SECURITY;REVOKE ALL ON "FinanceAsset" FROM PUBLIC;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT SELECT ON "FinanceAsset" TO encova_app;CREATE POLICY encova_server_read ON "FinanceAsset" FOR SELECT TO encova_app USING(true);END IF;
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON public."FinanceAsset" FROM %I',role_name);END IF;END LOOP;
 FOR item IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'encova_finance_asset_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',item.signature);FOREACH role_name IN ARRAY ARRAY['anon','authenticated','encova_app'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',item.signature,role_name);END IF;END LOOP;END LOOP;
 REVOKE ALL ON SEQUENCE public.finance_asset_number FROM PUBLIC;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION encova_finance_asset_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID) TO encova_app;END IF;
END $$;
COMMIT;
